\begin{annexitem}{annex:p03-w03-p03-026-host-los-tarski}{thm:p03-los-tarski}{The \L o\'s--Tarski theorem as stated in the overview}
\begin{proof}
The equivalence of closure under substructures with universal
axiomatizability, in both directions, is
\cref{thm:p03-w03-p03-026-los-tarski-class}, proved at
\cref{annex:p03-w03-p03-026-los-tarski-class}.  The sentence statement, in
both directions, is item~1 of \cref{thm:p03-w03-p03-026-los-tarski-sentence}
with \(S=\varnothing\), proved at
\cref{annex:p03-w03-p03-026-los-tarski-sentence}.
\end{proof}
\end{annexitem}

\begin{annexitem}{annex:p03-w03-p03-026-host-chang-los-suszko}{thm:p03-chang-los-suszko}{The Chang--\L o\'s--Suszko theorem as stated in the overview}
\begin{proof}
For \(\mathcal K=\operatorname{Mod}(T)\), the two conditions are items~1
and~4 of \cref{thm:p03-w03-p03-026-chang-los-suszko}; their equivalence, in
both directions, is proved at
\cref{annex:p03-w03-p03-026-chang-los-suszko}.
\end{proof}
\end{annexitem}
